head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > groupbyFilterBox]<br/>GridView 에 적용되었던 필터링 이력을 관리하는 GroupFilterBox 영역을 활성화 합니다.",
    "validation" : [
        "groupbyZone=true 인 경우에만 동작합니다.",
        "true 설정 시, 필터링 이력을 목록으로 제공하는 GroupFilterBox 영역을 활성화합니다.",
        "true 설정 시, GroupFilterBox 에서 필터링 여부를 설정할 수 있고 목록 선택 시 이전 필터링을 적용할 수 있습니다.",
        "false 설정 시, GroupFilterBox 영역을 비활성화합니다.",
        "미설정 시, GroupFilterBox 영역을 비활성화합니다.",
        "GroupFilterBox 의 목록을 선택하여 필터링 및 GroupBy 정보가 변경되어도 ongroupby 이벤트는 발생하지 않습니다.",
        "groupby() 메소드 또는 groupbyZone 기능으로 GroupBy 만 적용되면 필터링 이력이 추가되지 않습니다.",
        "customFilterBox=true 이면 GroupBy 없이 CustomFilter, FilterList 로 적용된 필터 이력도 추가됩니다.",
        "GroupFilterBox 의 체크박스 해제 시 필터링 적용이 제거됩니다.",
        "GroupFilterBox 의 X 버튼 클릭 시 저장된 필터링 이력이 모두 제거됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con 셀렉트박스 초기값 : gdl_boolean 코드값 "2"(=true)
    //  - groupbyFilterBox=true 로 GroupFilterBox 영역 표시 시연
    //  - customFilterBox=true 로 GroupBy 없이도 필터 이력이 추가되는 상태 시연
    //  - 정적 select1 은 초기 selectedIndex 미적용이므로 onpageload 에서 명시 설정
    con_groupbyFilterBox.setValue("2");
    con_customFilterBox.setValue("2");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - con_groupbyFilterBox / con_customFilterBox : 공통 gdl_boolean → getText() ('' 미설정 / 'true' / 'false')
//  - groupbyZone / useFilterList 는 고정 전제(항상 true) : groupbyFilterBox 는 groupbyZone=true 에서만 동작
//  - groupbyFilterBox 는 렌더타임 속성이므로 con 변경 후 [Target 재생성](btn_createTarget→comp_init)으로만 반영
//  - groupbyZone=true && groupbyFilterBox=true 이면 엔진이 <div class='w2grid_groupbyFilterBox' id='..._groupbyFilterBox_div'> 를 렌더
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con 값 : gdl_boolean 은 getText() 로 라벨('' / 'true' / 'false') 읽기
    let vGroupbyFilterBox = con_groupbyFilterBox.getText();
    let vCustomFilterBox = con_customFilterBox.getText();

    // 고정 전제 : groupbyZone / useFilterList / showSortableUseFilter 는 항상 true
    let properties = { groupbyZone: true, useFilterList: true, showSortableUseFilter: true };
    // groupbyFilterBox : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    if (vGroupbyFilterBox === 'true') {
        properties.groupbyFilterBox = true;
    } else if (vGroupbyFilterBox === 'false') {
        properties.groupbyFilterBox = false;
    }
    // customFilterBox : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    if (vCustomFilterBox === 'true') {
        properties.customFilterBox = true;
    } else if (vCustomFilterBox === 'false') {
        properties.customFilterBox = false;
    }

    let lblDesc = '[전제] groupbyZone=true / useFilterList=true 고정, col1~col4 헤더 useFilter=true (필터 아이콘 표시)'
        + '\n현재 groupbyFilterBox=' + (vGroupbyFilterBox === '' ? '(미설정)' : vGroupbyFilterBox)
        + ' / customFilterBox=' + (vCustomFilterBox === '' ? '(미설정)' : vCustomFilterBox) + ' (con 선택 후 [Target 재생성])'
        + '\n[절차] 필터 아이콘 클릭 -> 필터 적용 시 GroupFilterBox 목록에 이력 추가'
        + '\n목록 선택 시 이전 필터 재적용 / 체크박스 해제 시 필터 제거 / X 버튼으로 이력 전체 제거'
        + '\n[확인] [GroupFilterBox 상태 확인] 버튼으로 영역 표시 / 이력 수 / 체크박스 / 표시 행 수 관찰'
        + '\n[관찰] 목록 선택으로 필터가 바뀌어도 ongroupby 는 발생하지 않음 (헤더 컬럼을 GroupBy Zone 으로 드래그할 때만 ongroupby 발생)';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    let cList = $c.gcm.createCList(properties);

    // GridView 와 바인딩할 DataList 동적 생성 (4 Column, 6 Row : 그룹핑/필터 시연용 중복 데이터)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // target 생성 (useFilter Header Column 4개 + ongroupby 핸들러)
    await scwin.createGridView(cList);
}



// 그룹핑/필터 시연용 데이터 (col1 에 중복값 → GroupBy / 필터 기준 컬럼으로 사용)
scwin.fillData = function () {
    let rows = [
        { col1: "서울", col2: "강남", col3: "A", col4: "100" },
        { col1: "서울", col2: "송파", col3: "B", col4: "200" },
        { col1: "부산", col2: "해운대", col3: "C", col4: "300" },
        { col1: "부산", col2: "수영", col3: "D", col4: "400" },
        { col1: "대구", col2: "수성", col3: "E", col4: "500" },
        { col1: "대구", col2: "달서", col3: "F", col4: "600" }
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성 (useFilter="true" Header Column + ongroupby 이벤트 연결)
scwin.createGridView = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' id="" dataList="data:dlt_bind" ev:ongroupby="scwin.target1_ongroupby" style="width:560px;height:480px;">';
    s += '<w2:caption style="" id="caption1" value="groupbyFilterBox 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="140" style="" inputType="text" id="column1" value="지역" useFilter="true"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="column2" value="상세" useFilter="true"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="column3" value="구분" useFilter="true"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="값" useFilter="true"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="140" style="" inputType="text" id="col1"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="col2"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// ongroupby : 헤더 컬럼을 GroupBy Zone 으로 드래그하면 발생
//  - GroupFilterBox 목록 선택으로 필터/GroupBy 가 바뀌어도 이 이벤트는 발생하지 않음(@spec) → 발생 시에만 출력하여 대비
scwin.target1_ongroupby = function (options) {
    options.groupbyHeader = [
        {colSpan: 4, inputType: 'expression', expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: 'left'}
    ];
    options.hideFooter = true;

    target1.groupby(options);

    wf_body_bottom.getObj("scwin").setReturnValue("[ongroupby 발생] GroupBy 가 적용되었습니다. (드래그로만 발생, 목록 선택 시엔 미발생)");
}



// 확인 : GroupFilterBox 영역 표시 / 저장된 필터 이력 수 / 필터 적용 체크박스 상태 / 현재 표시 행 수 를 실측 출력
//  - 영역 div(w2grid_groupbyFilterBox) 존재 = 활성화 여부 (groupbyZone=true && groupbyFilterBox=true 에서만 렌더)
//  - groupbyFilterBox_history.length = 저장된 필터 이력 수 (목록 항목 수)
//  - apply 체크박스(_groupbyFilterBox_apply) checked = 현재 필터 적용 여부
//  - 표시 행 수 = 필터 적용 결과 화면에 남은 데이터 행 수(숨김 filler Row 제외)
scwin.btn_check_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[옵션] groupbyFilterBox=" + target1.options.groupbyFilterBox
        + " / groupbyZone=" + target1.options.groupbyZone
        + " / customFilterBox=" + target1.options.customFilterBox);

    let box = document.querySelector("div[id$='_groupbyFilterBox_div']");
    bottom.setReturnValue("[GroupFilterBox 영역] " + (box !== null ? "활성화(표시됨)" : "비활성화(표시안됨)"));

    let histLen = (target1.groupbyFilterBox_history) ? target1.groupbyFilterBox_history.length : 0;
    bottom.setReturnValue("[저장된 필터 이력 수] " + histLen + " 건");

    let apply = document.querySelector("input[id$='_groupbyFilterBox_apply']");
    bottom.setReturnValue("[필터 적용 체크박스] " + (apply ? (apply.checked ? "체크됨(필터 적용 중)" : "해제됨(필터 미적용)") : "없음"));

    // 현재 화면에 표시된 데이터 행 수 (필터 적용 결과 방증)
    let tbody = document.getElementById(target1.id + "_body_tbody");
    let dataRows = 0;
    if (tbody) {
        let trs = tbody.querySelectorAll("tr");
        for (let i = 0; i < trs.length; i++) {
            let tr = trs[i];
            if (tr.style.display === "none" || tr.className.indexOf("w2grid_hidedRow") >= 0) {
                continue;
            }
            dataRows++;
        }
    }
    bottom.setReturnValue("[현재 화면 표시 행 수] " + dataRows + " 행");
}
